#include <item/AbsorptionSashWire.hpp>
void AbsorptionSashCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,
    const std::string& password,const std::string& path,const std::vector<BulkSource>& sources,
    auriga::item::ItemKey clearKey,auriga::item::ItemKey stoleKey,const std::array<auriga::item::ItemGrant,2>& donors)
{
    using namespace auriga::item;CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"sash private SQL connects");auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-absorption-sash-worker").has_value(),"sash actual item worker starts");
    const auto issued=static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count());
    for(unsigned n=0;n<sources.size();++n){
        std::cout<<"SASH_SQL_CASE="<<n<<std::endl;const auto key=sources[n].grant.key;const auto& profile=*catalog->FindAbsorptionSash(key);const ItemOwner owner{ItemOwnerKind::Character,63000u+n};
        const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4},ItemStorageLayout{{owner,ItemStorageKind::Equipment,1},29,1,1}};const std::array wallets{ItemWallet{owner,WalletCurrency::Gold,1,100000000}};
        Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,wallets).has_value(),"sash owner provisioned");auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();unsigned serial=0;bool replay=false;
        const auto op=[&](){++serial;return std::array<std::uint8_t,16>{0xB6,static_cast<std::uint8_t>(n),static_cast<std::uint8_t>(serial),static_cast<std::uint8_t>(serial>>8)};};
        const auto apply=[&](const ItemCommit& commit){std::optional<runtime::CommitOutcome> got;Check(runtime::RequestCommit(owner,state.fence.sessionGeneration,commit,[&](auto out){got=std::move(out);}),"sash commit queues");for(unsigned spin=0;!got && spin<1000;++spin){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(got && got->write && got->state,"sash commit saves and reloads");replay=got->write->replay;state=*got->state;};
        const auto find=[&](ItemInstanceId id)->const PersistentItem&{const auto i=std::ranges::find(state.items,id,&PersistentItem::id);Check(i!=state.items.end(),"sash actual owned item exists");return *i;};
        const auto absent=[&](ItemInstanceId id){return std::ranges::find(state.items,id,&PersistentItem::id)==state.items.end();};
        const auto grant=[&](ItemGrant spec){spec.createdAtUtcMs=issued;const auto ids=runtime::PeekInstanceIds(1);Check(ids.size()==1,"sash birth reserves a real native ID");runtime::SpendInstanceIds(1);apply(MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,spec,ids).value());return ids.front();};
        const auto relog=[&](){const auto before=state.items;const auto generation=persistence::ClaimOwnerSession(sql,*catalog,owner).value();state=persistence::LoadItemOwner(sql,*catalog,owner,generation).value();Check(before==state.items,"sash donor and percentage survive new SQL owner session");};
        const auto write=[&](const std::string& phase,const char* kind,const auto& bytes){std::ofstream f(path+"."+std::to_string(n)+"."+phase+"."+kind+".hex");for(auto b:bytes){const auto v=static_cast<unsigned char>(b);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';Check(f.good(),"sash actual packet exported");};
        const auto output=[&](const std::string& phase){const auto inv=EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value();Check(DecodeTypedInventory(inv,owner).has_value(),"sash real inventory decodes natively");write(phase,"inventory",inv);write(phase,"details",EncodeTypedItemDetails(*catalog,state.items).value());CostumeAppearance look{313,state.fence.revision};for(const auto& i:state.items)if(i.placement && i.placement->kind==ItemStorageKind::Equipment){const auto* e=catalog->Find(i.key);if(e->base.appearanceProfile){auto model=catalog->FindAppearance(*e->base.appearanceProfile)->modelAsset;if(i.sash)look.absorptionSash=model;else if(i.regalia && std::get<ItemRegaliaRow>(e->category).kind==RegaliaKind::Stole)look.models[5]=model;}}write(phase,"appearance",EncodeCostumeAppearance(look,5).value());};
        const auto id=grant({key}),second=grant({key}),tool=grant({clearKey,0,2}),stole=grant({stoleKey});auto donorSpec=donors[n%2];donorSpec.tryMagic=true;donorSpec.magicChanceBp=10000;const auto donor=grant(donorSpec);const auto copied=find(donor).attributes;
        Check(find(id).sash && !find(id).sash->donor && !find(id).regalia,"actual birth uses independent absorption state");Check(std::ranges::any_of(copied.slots,[](const auto& b){return b.has_value();}),"actual donor has source magic attributes to preserve");
        AbsorptionSashActor actor;actor.admitted=actor.alive=true;actor.equipment={255,0,0,issued};const auto* use=catalog->FindUsePolicy(catalog->Find(key)->base.usePolicy);while(!(use->allowedClasses&(1u<<actor.equipment.characterClass)))++actor.equipment.characterClass;while(!(use->allowedSexes&(1u<<actor.equipment.sex)))++actor.equipment.sex;
        auto q=PrepareAbsorptionSash(*catalog,owner,state.items,state.wallets,id,donor,AbsorptionSashOperation::Absorb,actor).value();output("absorb_ready");write("absorb_ready","reply",EncodeAbsorptionSashReply(*catalog,0,101,id.Value(),donor.Value(),3,&q));
        const auto absorb=MakeAbsorptionSashCommit(*catalog,op(),state.fence,state.storages,state.items,state.wallets,id,donor,AbsorptionSashOperation::Absorb,actor,{}).value();apply(absorb.commit);Check(absent(donor) && find(id).sash->donor.has_value(),"absorption atomically destroys donor and saves copied state");for(unsigned j=0;j<8;++j)Check(find(id).sash->donor->attributes[j]==(copied.slots[j] && copied.slots[j]->valueScaled>0 ? copied.slots[j] : std::optional<BonusEntry>{}),"all eight original donor bonus slots survive SQL");const auto saved=state.items;apply(absorb.commit);Check(replay && state.items==saved,"absorption replay cannot destroy another donor");relog();output("absorbed");write("absorbed","reply",EncodeAbsorptionSashReply(*catalog,1,101,id.Value(),donor.Value(),3,&absorb.quote,1));
        apply(MakeEquipCommit(*catalog,op(),state.fence,state.storages,state.items,stole,actor.equipment).value());apply(MakeEquipCommit(*catalog,op(),state.fence,state.storages,state.items,id,actor.equipment).value());Check(find(id).placement->anchor==28 && find(stole).placement->anchor==11,"sash and six-bonus stole use independent simultaneous slots");const auto stats=BuildEquipmentStats(*catalog,owner,state.items).value();std::array<std::int64_t,MaximumBonusId+1> expected{};for(auto b:AbsorptionSashContributions(*catalog->FindSashDonor(donorSpec.key,donorSpec.refinementLevel),*find(id).sash))expected[static_cast<unsigned>(b.bonus)]+=b.valueScaled;for(auto b:find(stole).regalia->bonuses)if(b)expected[static_cast<unsigned>(b->bonus)]+=b->valueScaled;Check(stats.bonuses==expected,"equipped server totals include each real sash and stole component once");relog();output("equipped");
        apply(MakeUnequipCommit(*catalog,op(),state.fence,state.storages,state.items,id,{ItemStorageKind::Inventory,1,80},actor.equipment).value());q=PrepareAbsorptionSash(*catalog,owner,state.items,state.wallets,tool,id,AbsorptionSashOperation::Clear,actor).value();output("clear_ready");write("clear_ready","reply",EncodeAbsorptionSashReply(*catalog,0,102,tool.Value(),id.Value(),4,&q));const auto percent=find(id).sash->percent;const auto clear=MakeAbsorptionSashCommit(*catalog,op(),state.fence,state.storages,state.items,state.wallets,tool,id,AbsorptionSashOperation::Clear,actor,{}).value();apply(clear.commit);Check(!find(id).sash->donor && find(id).sash->percent==percent && find(tool).count==1,"clear saves unchanged percentage and one exact material debit");const auto cleared=state.items;apply(clear.commit);Check(replay && state.items==cleared,"clear replay cannot spend twice");relog();output("cleared");write("cleared","reply",EncodeAbsorptionSashReply(*catalog,1,102,tool.Value(),id.Value(),4,&clear.quote,1));
        q=PrepareAbsorptionSash(*catalog,owner,state.items,state.wallets,id,second,AbsorptionSashOperation::Combine,actor).value();output("combine_ready");write("combine_ready","reply",EncodeAbsorptionSashReply(*catalog,0,103,id.Value(),second.Value(),2,&q));const auto fresh=runtime::PeekInstanceIds(1).front();runtime::SpendInstanceIds(1);const auto combine=MakeAbsorptionSashCommit(*catalog,op(),state.fence,state.storages,state.items,state.wallets,id,second,AbsorptionSashOperation::Combine,actor,{1,q.minimumPercent,fresh}).value();const auto balance=state.wallets[0].balance;apply(combine.commit);Check(absent(id) && absent(second) && find(fresh).key==profile.next && find(fresh).sash->percent==q.minimumPercent && state.wallets[0].balance==balance-profile.goldCost,"successful combination atomically replaces both original IDs and charges original fee");const auto combined=state.items;apply(combine.commit);Check(replay && state.items==combined && state.wallets[0].balance==balance-profile.goldCost,"combine replay cannot mint a second result or charge twice");relog();output("combined");write("combined","reply",EncodeAbsorptionSashReply(*catalog,1,103,id.Value(),second.Value(),2,&q,1,fresh.Value()));
        if(profile.grade>1){const auto a=grant({key}),b=grant({key});const auto before=find(a);const auto fee=state.wallets[0].balance;const auto loss=MakeAbsorptionSashCommit(*catalog,op(),state.fence,state.storages,state.items,state.wallets,a,b,AbsorptionSashOperation::Combine,actor,{10000,0,{}}).value();apply(loss.commit);auto kept=before;++kept.revision;Check(find(a)==kept && absent(b) && state.wallets[0].balance==fee-profile.goldCost,"failed source combine saves first unchanged, destroys second and charges once");const auto lost=state.items;apply(loss.commit);Check(replay && lost==state.items,"failed combination replays exact recorded loss");relog();output("failed");write("failed","reply",EncodeAbsorptionSashReply(*catalog,1,104,a.Value(),b.Value(),2,&loss.quote,2));}
    }
    store.Stop();std::cout<<"SOURCE_ABSORPTION_SASH_WORKER=SUCCESS sources="<<sources.size()<<" checks="<<checks<<std::endl;
}
